/// Name-to-definition index.
///
/// [`LOCALES`] is sorted by name, so this is a binary search.
pub fn by_name(name: &str) -> Option<&'static GeneratedLocale> {
    match LOCALES.binary_search_by(|locale| locale.name.cmp(name)) {
        Ok(index) => Some(&LOCALES[index]),
        Err(_) => None,
    }
}

/// Every built-in locale name, in sorted order.
pub fn names() -> impl Iterator<Item = &'static str> {
    LOCALES.iter().map(|locale| locale.name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn locales_are_sorted_and_indexable() {
        assert_eq!(LOCALES.len(), LOCALE_COUNT);
        assert!(LOCALES.windows(2).all(|pair| pair[0].name < pair[1].name));
        for locale in &LOCALES {
            assert_eq!(
                by_name(locale.name).map(|found| found.name),
                Some(locale.name)
            );
            assert_eq!(locale.source_sha256.len(), 64);
            assert_eq!(locale.definition_sha256.len(), 64);
            if let Some(numerals) = locale.numerals {
                assert_eq!(numerals.len(), 10);
            }
        }
        assert_eq!(by_name("nope"), None);
    }
}
